import os, json

sessions_base = '/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference-3/play/users/u061/system/state/sessions'
if os.path.exists(sessions_base):
    for fname in os.listdir(sessions_base):
        if fname.endswith('.jsonl'):
            fpath = os.path.join(sessions_base, fname)
            with open(fpath, 'r') as f:
                content = f.read()

            # Look for a rectangular grid pattern (multiple lines of spaces and digits)
            lines = content.split('\n')
            for i, line in enumerate(lines):
                # Check for a grid-like row (only digits and spaces)
                if line.strip() and all(c.isdigit() or c in ' -' for c in line):
                    # Check if it's actually a grid row
                    parts = line.strip().split()
                    if len(parts) >= 10 and all(p.isdigit() for p in parts):
                        print(f"{fpath}:{i}: {line.strip()}")
                        if i > 0:
                            print(f"  Previous: {lines[i-1].split(':')[-1] if ':' in lines[i-1] else lines[i-1][:50]}")
                        break

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    result = [['4'] * cols for _ in range(rows)]

    for foreground_val in [1, 6]:
        cells = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == foreground_val:
                    cells.append((r, c, foreground_val))

        if len(cells) < 2:
            continue

        # Main diagonal (r-c)
        main_dict = {}
        for r, c, val in cells:
            key = r - c
            if key not in main_dict:
                main_dict[key] = []
            main_dict[key].append((r, c, val))

        for key, val_cells in main_dict.items():
            if len(val_cells) >= 2:
                sorted_cells = sorted(val_cells, key=lambda x: x[0])
                for i in range(len(sorted_cells)):
                    r1, c1, v1 = sorted_cells[i]
                    for j in range(i + 1, len(sorted_cells)):
                        r2, c2, _ = sorted_cells[j]
                        dr, dc = r2 - r1, c2 - c1
                        if abs(dr) == abs(dc):
                            steps = abs(dr)
                            for step in range(1, steps):
                                tr = r1 + int(dr * step / steps)
                                tc = c1 + int(dc * step / steps)
                                result[tr][tc] = str(v1)
                            result[r1][c1] = str(v1)
                            result[r2][c2] = str(v1)
                            break

        # Anti diagonal (r+c)
        anti_dict = {}
        for r, c, val in cells:
            key = r + c
            if key not in anti_dict:
                anti_dict[key] = []
            anti_dict[key].append((r, c, val))

        for key, val_cells in anti_dict.items():
            if len(val_cells) >= 2:
                sorted_cells = sorted(val_cells, key=lambda x: x[0])
                for i in range(len(sorted_cells)):
                    r1, c1, v1 = sorted_cells[i]
                    for j in range(i + 1, len(sorted_cells)):
                        r2, c2, _ = sorted_cells[j]
                        dr, dc = r2 - r1, c2 - c1
                        if abs(dr) == abs(dc):
                            steps = abs(dr)
                            for step in range(1, steps):
                                tr = r1 + int(dr * step / steps)
                                tc = c1 + int(dc * step / steps)
                                result[tr][tc] = str(v1)
                            result[r1][c1] = str(v1)
                            result[r2][c2] = str(v1)
                            break

    return result

